Locally at a smooth point $b \in B'^\mathrm{reg}$ the subvariety $B' \subset B$ is cut out by $k=\mathrm{codim} B'$ many functions $f_1,\dots,f_k\in \mathcal{O}_B$. We can associate invariant vector fields $X_i \in VM\: \rule[-3.5pt]{0.5pt}{11.5pt}\,{}_{B'}$ along the torus fibers so that $\Omega(X_i, \cdot)= H^* \mathrm{d} f_i$ for $i=1,\dots,k$. Let $m \in \mathcal{L}_b$ and $Y \in T_mM$, such that $DH(Y) \in T_bB'$, then
 \begin{align} \Omega(X_i,Y)=H^*\mathrm{d}f_i Y=\mathrm{d}f_i(DH(Y)) = 0. \label{eq:horizontal_vf}
 \end{align}
 Therefore, the connected components of the fiber of $\mathcal{L}$ over $b \in B'^\mathrm{reg}$ are integral submanifolds of the distribution $V\mathcal{L}=\mathrm{span}(X_1, \dots, X_k)$. Hence the connected components of the fibers of $\mathcal{L}_b \rightarrow B'^\mathrm{reg}$ are complex subtori. In particular, the subspace $V_b\mathcal{L} \subset V_bM$ is rational with respect to the lattice $\Lambda_b$. By definition, this is equivalent to $H_*T\mathcal{L}=TB'$ being rational with respect to the integral affine structure on $B$. Finally, by (\ref{eq:horizontal_vf}) we have $ V\mathcal{L} \subset (TB'^\mathrm{reg})^\perp \subset T^\vee B^\mathrm{reg} \cong VM$. The first inclusion is an equality both being of rank $k$.

\label{prop:Baraglia}
 Let \smash{$\underline{a} \in \mathcal{B}_{\mathrm{GL}(n,\mathbb{C})}^\mathrm{reg}$}. The identification of the tangent space $T_{\underline{a}}\mathcal{B}_{\mathrm{GL}(n,\mathbb{C})}$ with the dual of the tangent space to the fiber $T^\vee_L\mathrm{Jac}(\Sigma_{\underline{a}}) \cong H^0(\Sigma_{\underline{a}},K_\Sigma)$ is given by
 \begin{align*}
 t\colon \ \bigoplus\limits_{i=1}^n H^0\bigl(X,K_X^i\bigr) & \rightarrow H^0(\Sigma_{\underline{a}},K_{\Sigma_{\underline{a}}})
 \\
\sum\limits_{i=1}^n \alpha_i X_i & \mapsto \frac{1}{s_B} \sum\limits_{i=1}^n \alpha_i \pi^*X_i\bigl(\lambda^{n-i}+\pi^*a_2 \lambda^{n-2-i}+ \dots + \pi^*a_{n-i}\bigr),
 \end{align*}
 where $s_B=d \pi \in H^0\bigl(\Sigma_{\underline{a}},\pi^*K_X^{n-1}\bigr)$ vanishes at the branch divisor.

Using the section $s$, we can identify the Hitchin system over $\mathcal{B}'^\mathrm{reg}$ with the abelian scheme $\mathrm{Prym}(\Sigma/\mathcal{B}'^\mathrm{reg}) \rightarrow \mathcal{B}'^\mathrm{reg}$. By Theorem~\ref{theo:visible_Lagr}, the fiber $\mathcal{L}_b$ for $b \in \mathcal{B}'^\mathrm{reg}$ is a complex subtorus that by assumption contains $s(b)$. Hence, $\mathcal{L}$ defines an abelian subscheme $A \subset \mathrm{Prym}(\Sigma/\mathcal{B}'^\mathrm{reg})$. We obtain an exact sequence of abelian schemes over $\mathcal{B}'^\mathrm{reg}$
 \begin{align} 0 \rightarrow A \rightarrow \mathrm{Prym}(\Sigma/\mathcal{B}'^\mathrm{reg}) \rightarrow Q \rightarrow 0, \label{eq:exact_sequ}
 \end{align}
 where the quotient $Q$ is again an abelian scheme over $\mathcal{B}'^\mathrm{reg}$. Dually, we obtain an exact sequence of abelian schemes
 \begin{align} 0 \rightarrow Q^\vee \rightarrow \mathrm{Prym}(\Sigma/\mathcal{B}'^\mathrm{reg})^\vee \rightarrow A^\vee \rightarrow 0. \label{eq:dual_exact_sequ}
 \end{align}
 We can define a section \smash{$s'= \delta \circ s\colon \mathcal{B}'^\mathrm{reg} \rightarrow \mathrm{Hit}^{-1}_{G^{\rm L}}(\mathcal{B}'^\mathrm{reg}) \subset \mathcal{M}_{G^{\rm L}}$}. Acting by $Q^\vee$ on $s'\colon \mathcal{B}'^\mathrm{reg} \rightarrow \mathcal{M}_{G^{\rm L}}$ defines a submanifold \smash{$I \subset \mathrm{Hit}^{-1}(\mathcal{B}'^\mathrm{reg}) \subset \mathcal{M}_{G^{\rm L}}$}. We define $\mathcal{I}=\overline{I}$. We want to show that this is subintegrable system with regular locus $I$, i.e., the holomorphic symplectic form restricts to a non-degenerate form on~$I$ and $\mathrm{Hit}\: \rule[-3.5pt]{0.5pt}{11.5pt}\,{}_{\mathcal{I}}: \mathcal{I} \rightarrow \mathcal{B}'^\mathrm{reg}$ is an integrable system. First note that for all $b \in \mathcal{B}'^\mathrm{reg}$
 \[\dim \mathcal{I}_b=\dim(\mathrm{Prym}(\Sigma_b))-\dim \mathcal{L}_b=\frac 12 \dim \mathcal{M}(X,G)-\dim \mathcal{L}_b=\dim B'^\mathrm{reg}.
 \]
 Hence, the restricted Hitchin map will lead the correct number of commuting Hamiltonian functions and the fibers are complex tori by definition. To show that it forms a subintegrable system, it suffices to show that the tangent space of $\mathcal{I}$ at the section~$s'$ is a~symplectic vector space with the restriction of the symplectic form. The argument at a~general point follows by a~translation along the fibers of~$\mathcal{I}$. We identify the tangent spaces $T_{s(b)}\mathcal{M}_G \cong T_{s'(b)}\mathcal{M}_{G^{\rm L}}$ using~$\delta$. Then the vertical tangent spaces to $V\mathcal{L}$ and $V\mathcal{I}$ are complementary by definition. Denote by~$H'_b=Ds'(T_b\mathcal{B}'^\mathrm{reg})$ the tangent space to the image of the section~$s'$ at~$b$. Tangent vectors in~$H'_b$~pair to zero with the vertical tangent vectors in $V_b\mathcal{L}$ as $\mathcal{L}$ is Lagrangian. On~the other hand, the symplectic form on $T_{s'(b)}\mathcal{M}_{G^{\rm L}}$ is non-degenerate. Hence, it induces an isomorphism $(H'_b)^\vee \cong V_b\mathcal{I}$ or equivalently the symplectic form restricts to a non-degenerate symplectic form on $T_{s'(b)} \mathcal{I}=H'_b \oplus V_b \mathcal{I}$.

\label{prop:non-isomorphic_pillow}
	The canonical covers $\Sigma_1$ and $\Sigma_2$ are non-isomorphic.
	In particular, $(X,q_1) \not \cong (X,q_2)$, i.e., there does not exist an automorphism $\varphi\colon X \rightarrow X$, such that $\varphi^* q_1 = q_2$.
